function validate([grades]) {
  if (!Array.isArray(grades) || grades.length < 1 || grades.length > 100000) return 'grades needs 1 to 10^5 values.';
  if (grades.some(g => !Number.isInteger(g) || g < 1 || g > 100000)) return 'Each grade is a whole number from 1 to 10^5.';
  return null;
}

