function maximumGroups(grades) {
  const n = grades.length;
  // Sizes 1, 2, ..., k need k(k + 1) / 2 students; solve k^2 + k - 2n = 0 for k.
  const root = Math.sqrt(8 * n + 1);
  let groups = Math.floor((root - 1) / 2);

  // Guard against floating-point rounding on either side.
  while (groups * (groups + 1) / 2 > n) {
    groups--;
  }
  while ((groups + 1) * (groups + 2) / 2 <= n) {
    groups++;
  }
  return groups;
}

