function maximumGroups(grades) {
  // Build the groups for real: sort ascending, cut sizes 1, 2, 3, ... and
  // merge a final piece that breaks a rule into the group before it.
  const sorted = [...grades].sort((a, b) => a - b);
  const total = list => list.reduce((x, y) => x + y, 0);
  const built = [];
  let index = 0;
  while (index < sorted.length) {
    const piece = sorted.slice(index, index + built.length + 1);
    index += piece.length;
    const last = built[built.length - 1];
    if (last && (piece.length <= last.length || total(piece) <= total(last))) last.push(...piece);
    else built.push(piece);
  }
  // Double-check that the groups follow both rules.
  for (let i = 1; i < built.length; i++) {
    if (built[i].length <= built[i - 1].length || total(built[i]) <= total(built[i - 1])) return -1;
  }
  return built.length;
}

