function generate(rand, size) {
  let n;
  if (size === 'large') {
    n = 1500 + Math.floor(rand() * 501);
  } else if (rand() < 0.4) {
    // Exactly 1 + 2 + ... + k students, or one fewer: the boundaries of the answer.
    const k = 1 + Math.floor(rand() * 5);
    n = Math.max(1, k * (k + 1) / 2 - Math.floor(rand() * 2));
  } else {
    n = 1 + Math.floor(rand() * 16);
  }
  const top = size === 'large' ? 100000 : (rand() < 0.3 ? 2 : 20);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
